+
+/// Python `round()`: round half to even (banker's rounding).
+fn py_round(x: f64) -> f64 {
+    let floor = x.floor();
+    let frac = x - floor;
+    if frac < 0.5 {
+        floor
+    } else if frac > 0.5 {
+        floor + 1.0
+    } else if (floor as i64) % 2 == 0 {
+        floor
+    } else {
+        floor + 1.0
