+    let (nph, npw) = least_distortion_fit(
+        i_nph,
+        i_npw,
+        img_h,
+        img_w,
+        token_patch_h,
+        token_patch_w,
+        min_num_tokens,
+        max_num_tokens,
+    )
+    .or_else(|| {
+        least_distance_fit(
+            i_nph,
+            i_npw,
+            min_num_tokens,
+            max_num_tokens,
+            token_patch_h,
+            token_patch_w,
+        )
+    })
+    .ok_or_else(|| {
+        TransformError::ShapeError(format!(
+            "resolution fitting failed for {img_w}x{img_h} image within [{min_num_tokens}, {max_num_tokens}] tokens"
+        ))
+    })?;
